CREATE OR REPLACE FUNCTION public.cadastrar_produto_com_variacao(p_nome_produto text, p_nome_variacao text, p_preco numeric, p_peso_kg numeric, p_validade_dias integer, p_prazo_dias_uteis integer, p_tem_lactose boolean, p_tem_gluten boolean, p_estoque_inicial integer DEFAULT 0, p_categoria_id integer DEFAULT NULL::integer, p_descricao_produto text DEFAULT NULL::text, p_descricao_variacao text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_produto integer; v_variacao integer;
BEGIN
  IF auth.uid() IS NULL OR NOT privado.eh_admin() THEN
    RAISE EXCEPTION 'Apenas o administrador pode cadastrar produtos.' USING ERRCODE = '42501';
  END IF;
  IF p_nome_produto IS NULL OR btrim(p_nome_produto) = ''
    OR p_nome_variacao IS NULL OR btrim(p_nome_variacao) = ''
    OR p_preco IS NULL OR p_preco::text IN ('NaN','Infinity','-Infinity') OR p_preco < 0 OR p_preco <> round(p_preco,2)
    OR p_peso_kg IS NULL OR p_peso_kg::text IN ('NaN','Infinity','-Infinity') OR p_peso_kg <= 0 OR p_peso_kg <> round(p_peso_kg,3)
    OR p_validade_dias IS NULL OR p_validade_dias <= 0
    OR p_prazo_dias_uteis IS NULL OR p_prazo_dias_uteis < 0
    OR p_tem_lactose IS NULL OR p_tem_gluten IS NULL
    OR p_estoque_inicial IS NULL OR p_estoque_inicial < 0 THEN
    RAISE EXCEPTION 'Preencha todos os dados da primeira variação com valores válidos.';
  END IF;
  INSERT INTO public."Produto" (nome_prd, id_cat_fk, descricao_prd)
  VALUES (btrim(p_nome_produto), p_categoria_id, p_descricao_produto) RETURNING id_prd INTO v_produto;
  INSERT INTO public."Produto_Variacao" (
    id_prd_fk, nome_var, preco_var, peso_var, validade_dias_var,
    prazo_producao_dias_uteis_var, tem_lactose_var, tem_gluten_var, descricao_var
  ) VALUES (
    v_produto, btrim(p_nome_variacao), p_preco, p_peso_kg, p_validade_dias,
    p_prazo_dias_uteis, p_tem_lactose, p_tem_gluten, p_descricao_variacao
  ) RETURNING id_var INTO v_variacao;
  UPDATE public."Estoque" SET quantidade_est = p_estoque_inicial
  WHERE id_prd_fk = v_produto AND id_var_fk = v_variacao;
  RETURN jsonb_build_object('produto_id', v_produto, 'variacao_id', v_variacao);
END;
$function$

