CREATE OR REPLACE FUNCTION privado.exigir_variacao_produto()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_produto integer;
BEGIN
  IF TG_TABLE_NAME = 'Produto' THEN v_produto := NEW.id_prd;
  ELSE v_produto := OLD.id_prd_fk; END IF;
  IF EXISTS (SELECT 1 FROM public."Produto" WHERE id_prd = v_produto)
    AND NOT EXISTS (SELECT 1 FROM public."Produto_Variacao" WHERE id_prd_fk = v_produto) THEN
    RAISE EXCEPTION 'O produto % precisa ter pelo menos uma variação.', v_produto USING ERRCODE = '23514';
  END IF;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION privado.conferir_saldo_reservado()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_chave record; v_contador integer; v_soma bigint;
BEGIN
  FOR v_chave IN
    SELECT DISTINCT ids.produto, ids.variacao FROM (VALUES
      (CASE WHEN TG_OP <> 'INSERT' THEN OLD.id_prd_fk END,
       CASE WHEN TG_OP <> 'INSERT' THEN OLD.id_var_fk END),
      (CASE WHEN TG_OP <> 'DELETE' THEN NEW.id_prd_fk END,
       CASE WHEN TG_OP <> 'DELETE' THEN NEW.id_var_fk END)
    ) ids(produto,variacao) WHERE ids.produto IS NOT NULL AND ids.variacao IS NOT NULL
  LOOP
    SELECT reservada_est INTO v_contador FROM public."Estoque"
    WHERE id_prd_fk = v_chave.produto AND id_var_fk = v_chave.variacao;
    SELECT coalesce(sum(quantidade_res), 0) INTO v_soma FROM public."Reserva_Estoque"
    WHERE id_prd_fk = v_chave.produto AND id_var_fk = v_chave.variacao AND status_res = 'reservada';
    IF coalesce(v_contador, 0)::bigint <> v_soma THEN
      RAISE EXCEPTION 'Saldo reservado inconsistente para produto %, variação %.', v_chave.produto, v_chave.variacao USING ERRCODE = '23514';
    END IF;
  END LOOP;
  RETURN NULL;
END;
$function$

